    public static class DownloadCoreQa {
        static void Need(bool value,string message){if(!value)throw new Exception(message);}
        public static void Verify(List<string> results){
            var first=PassiveSlots.Select(new[]{"music","battery"},null);Need(first[0]=="battery"&&first[1]=="music","Default slot placement");var second=PassiveSlots.Select(new[]{"music","download","battery"},first);Need(second[0]=="download"&&second[1]=="music","Stable surviving music side");var third=PassiveSlots.Select(new[]{"fps","music","download","battery"},second);Need(third[0]=="download"&&third[1]=="fps","Priority or stable download side");var fourth=PassiveSlots.Select(new[]{"music","download"},third);Need(fourth[0]=="download"&&fourth[1]=="music","Placement jitters after FPS stops");
            DateTime now=DateTime.UtcNow;string text="\"appid\" \"570\"\n\"name\" \"Fixture game\"\n\"StateFlags\" \"1048576\"\n\"BytesDownloaded\" \"350\"\n\"BytesToDownload\" \"1000\"";var download=DownloadWatcher.ParseSteam(text,now,now);Need(download!=null&&download.Received==350&&download.Total==1000,"Steam real-byte fixture");Need(DownloadWatcher.ParseSteam(text.Replace("1048576","1049088"),now,now)==null,"Paused Steam download shown");Need(DownloadWatcher.ParseSteam(text,now.AddMinutes(-1),now)==null,"Stale Steam progress shown");Need(DownloadWatcher.ParseSteam(text.Replace("350","1000"),now,now)==null,"Completed Steam download shown");Need(DownloadWatcher.ParseSteam(text.Replace("1048576","4"),now,now)==null,"Installed app shown as download");var snapshot=new DownloadSnapshot{Items=new[]{download,new ActiveDownload{Received=650,Total=1000}}};Need(Math.Abs(snapshot.Fraction.Value-.5)<.0001,"Weighted progress");snapshot.Items[1].Total=-1;Need(!snapshot.Fraction.HasValue,"Unknown total invented percentage");
            results.Add("PASS: Stable priority slots across all competing indicators; Steam byte counters, paused/completed/installed/stale rejection; weighted progress and unknown-size semantics. Fixtures only.");
        }
    }
