each(var v in new FrameworkElement[]{compact,compactText,clock,compactTimer,compactFps,compactDownload}){var clip=System.Windows.Media.VisualTreeHelper.GetClip(v);debug.Add(v.GetType().Name+" actual="+v.RenderSize+" pos="+v.TranslatePoint(new Point(),canvas)+" clip="+(clip==null?"null":clip.Bounds.ToString())+" own="+(v.Clip==null?"null":v.Clip.Bounds.ToString()));}File.WriteAllLines(Path.Combine(root,"downloads-debug-"+frame+".txt"),debug);}frame++;if(t>6){timer.Stop();File.WriteAllLines(Path.Combine(root,"downloads-trace.csv"),trace);background.Close();Close();}};timer.Start();}
